                    const i = toIdx(v), p = pos.b[i], r = i >> 3, c = i & 7, el = sqEls[v];
                    let cls = 'sq'; if ((r + c) & 1) cls += ' d'; if (selectedSquare === i) cls += ' sel';
                    const targetMove = validMoves.find(m => m.to === i); if (targetMove) cls += ' tgt' + (targetMove.captures.length > 0 ? ' cap' : '');
