    function toggleFullscreen() {
        const isFs = win.classList.toggle('fullscreen');
        fullscreenBtn.textContent = isFs ? '⤡' : '⛶';
        fullscreenBtn.title = isFs ? 'Свернуть' : 'На весь экран';
    }
    fullscreenBtn.addEventListener('click', toggleFullscreen);

    // ============================================================
